Let \(V=\{v_0<\cdots<v_N\}\) be a finite forward-invariant set containing
		the critical values of \(f\), and set \(U_j=(v_{j-1},v_j)\). The
		\emph{extended incidence matrix}\index{matrix!extended incidence}
		\(\widehat A=(\widehat a_{ij})\) is defined by
		\[
		\widehat a_{ij}
		=
		\left|
		\left\{
		\text{connected components of } f^{-1}(U_j)\cap U_i
		\right\}
		\right|.
		\]

Let $S = S_{g,n}$ be a connected, orientable surface of negative Euler characteristic, and let $\phi \in \mathrm{Mod}(S)$ be a pseudo-Anosov mapping class. The \emph{mapping torus}\index{mapping torus} of $\phi$ is the compact, orientable 3-manifold defined by the suspension space:
		\begin{equation}
			M_\phi = (S \times [0,1]) / \sim, \quad \text{where } (x, 1) \sim (\phi(x), 0).
		\end{equation}

For an integral cohomology class \(\alpha \in H^1(M; \mathbf{Z})\), the \emph{Thurston semi-norm}\index{norm!Thurston} is defined by
		\begin{equation}
			\|\alpha\|_T = \min \left\{ \chi_-(S) \ \middle|\ \begin{array}{l} S \subset M \text{ is a properly embedded,} \\ \text{oriented surface dual to } \alpha \end{array} \right\},
		\end{equation}
		where $\chi_-(S)$ minimizes the complexity across all components $S_i$ of $S$ via:
		\begin{equation}
			\chi_-(S) = \sum_{i} \max\big(0, -\chi(S_i)\big).
		\end{equation}
		and \(S_i\) denotes the connected components of \(S\). The semi-norm extends uniquely to \(H^1(M;\mathbf R)\) by homogeneity and continuity. It is
		usually referred to as the \emph{Thurston norm}.

\label{thm:fried_continuity}
		Let $M$ be a compact, oriented, fibered hyperbolic 3-manifold, and let $\mathcal{C}_F \subset H^1(M; \mathbf R)$ be a fibered cone. The function $f: \mathcal{C}_F \cap H^1(M; \mathbf{Z}) \to \mathbf R_{\geq 0}$ defined by 
		\begin{equation}
			f(\alpha) = \frac{1}{\log K(\alpha)}
		\end{equation}
		extends uniquely to a continuous, real-analytic, and strictly concave function on the entire open cone $\mathcal{C}_F$. Furthermore, $f$ is homogeneous of degree 1, satisfying:
		\begin{equation}
			f(t\alpha) = t f(\alpha) \quad \text{for all } t > 0,
		\end{equation}
		and fulfills the boundary condition:
		\begin{equation}
			\lim_{\alpha \to \partial \mathcal{C}_F} f(\alpha) = 0.
		\end{equation}

\label{thm:mcmullen_teich_poly}
		For each fibered face $F \subset H^1(M; \mathbf R)$, there exists a polynomial $\Theta_F \in \mathbf{Z}[G]$, called the Teichmüller polynomial, that completely determines the stretch factors of all monodromies in the fibered cone $\mathcal{C}_F$. 

		Explicitly, any integral cohomology class $\alpha \in \mathcal{C}_F \cap H^1(M; \mathbf{Z})$ specifies a group homomorphism $\alpha: G \to \mathbf{Z}$. This induces a ring homomorphism $\alpha_*: \mathbf{Z}[G] \to \mathbf{Z}[t^{\pm 1}]$ defined on the basis elements by $\alpha_*(g) = t^{ \alpha(g) }$. The stretch factor $K(\alpha)$ of the pseudo-Anosov monodromy is exactly equal to the largest real root of the single-variable specialized polynomial:
		\begin{equation}
			\alpha_*(\Theta_F)(t) = 0.
		\end{equation}

\label{prop:bi_perron_units}
		Let $m \geq 2$ and let $a_1, \dots, a_{m-1}$ be non-negative integers such that the vector
		\[
		v = (\underbrace{1,\dots,1}_{a_{m-1}}, \, \underbrace{2,\dots,2}_{a_{m-2}}, \, \dots, \, \underbrace{m-1,\dots,m-1}_{a_1}, \, m)
		\]
		is a primitive integral vector. Then, for any integer $a_m \geq 3 + 2(a_1 + \dots + a_{m-1})$, the largest real root of the reciprocal polynomial
		\begin{equation*}
			x^{2m} - a_1 x^{2m-1} - \dots - a_{m-1} x^{m+1} - a_m x^m - a_{m-1} x^{m-1} - \dots - a_1 x + 1 = 0
		\end{equation*}
		is a bi-Perron unit and corresponds precisely to the stretch factor of a pseudo-Anosov map on a connected surface.
